export type MathQuestion = {
  id: string;
  question: string;
  /** Emoji / symbol shown above the question (not used when clockTime is set) */
  image?: string;
  /** When present, an analog clock face is rendered instead of/alongside the image */
  clockTime?: { hour: number; minute: number };
  options: string[];
  correct: string;
  hint: string;
};

export type MathLesson = {
  title: string;
  /** UK National Curriculum year group this lesson is written for (1-6) */
  year: number;
  /** Curriculum strand, e.g. "Number - place value" */
  strand: string;
  questions: MathQuestion[];
};

